CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS scenes(id uuid PRIMARY KEY,name text NOT NULL,status text NOT NULL DEFAULT 'created',created_at timestamptz NOT NULL DEFAULT now(),failure jsonb,room jsonb);
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY,scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'queued',from_stage text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,error jsonb);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_one_active ON jobs(scene_id) WHERE status IN ('queued','running');
CREATE TABLE IF NOT EXISTS stage_runs(scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,stage text NOT NULL,algorithm text NOT NULL,config_hash text NOT NULL,status text NOT NULL,manifest jsonb,error jsonb,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scene_id,stage));
CREATE TABLE IF NOT EXISTS objects(scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,id text NOT NULL,label text NOT NULL,label_vi text,box jsonb NOT NULL,attributes jsonb NOT NULL DEFAULT '{}',best_views jsonb NOT NULL DEFAULT '[]',embedding vector(1024),PRIMARY KEY(scene_id,id));
CREATE INDEX IF NOT EXISTS objects_embedding_idx ON objects USING hnsw(embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS relations(scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,subject_id text NOT NULL,predicate text NOT NULL,object_id text,value real);
CREATE TABLE IF NOT EXISTS messages(id bigserial PRIMARY KEY,scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,role text NOT NULL,content jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scene_events(id bigserial PRIMARY KEY,scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,event text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
